package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.kinetics.base.KineticBlockEntity;
import com.simibubi.create.content.kinetics.chainConveyor.*;
import com.simibubi.create.content.kinetics.motor.CreativeMotorBlock;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.world.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;

public class ChainRidingGameTests {
    private static final BlockPos P=new BlockPos(1,6,2),Q=P.east(5);
    private static ChainConveyorBlockEntity place(GameTestHelper h,BlockPos pos){h.setBlock(pos,AllBlocks.CHAIN_CONVEYOR);return h.getBlockEntity(pos,ChainConveyorBlockEntity.class);}
    private static Player player(GameTestHelper h){var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(Vec3.atBottomCenterOf(h.absolutePos(P)).add(0,-2,3.5));player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));return player;}
    private static void aim(Player player,Vec3 target){var diff=target.subtract(player.getEyePosition());player.setYRot((float)Math.toDegrees(Math.atan2(-diff.x,diff.z)));player.setXRot((float)-Math.toDegrees(Math.atan2(diff.y,Math.hypot(diff.x,diff.z))));}
    private static ChainConveyorInteraction.Packet request(Player player,ChainConveyorBlockEntity conveyor){aim(player,conveyor.getPackagePosition(0,null));var from=player.getEyePosition();var hit=ChainConveyorInteraction.trace(conveyor,from,from.add(player.getLookAngle().scale(player.blockInteractionRange()+1)));if(hit==null)throw new AssertionError("Expected actual chain ray hit");return new ChainConveyorInteraction.Packet(conveyor.getBlockPos(),hit.connection(),hit.position(),ChainConveyorInteraction.RIDE,0);}
    private static KineticBlockEntity motor(GameTestHelper h,int speed){h.setBlock(P.below(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.UP));var motor=h.getBlockEntity(P.below(),KineticBlockEntity.class);motor.setGeneratedSpeed(speed);return motor;}
    @GameTest public void actualWrenchRayBoardsWithoutVehicleGravityOrFlightOverrides(GameTestHelper h){var conveyor=place(h,P);var player=player(h);player.fallDistance=12;h.assertTrue(ChainConveyorInteraction.apply(player,request(player,conveyor)),"Server accepted actual tool/ray selection");h.assertTrue(ServerChainConveyorHandler.get(player)!=null,"Authoritative ride exists");h.assertFalse(player.isPassenger()||player.isNoGravity()||player.getAbilities().flying,"Source skyhook is elastic normal player movement");h.assertValueEqual(player.fallDistance,0d,"Valid boarding resets fall distance");h.assertValueEqual(player.getMainHandItem().getCount(),1,"Wrench not consumed");ServerChainConveyorHandler.stop(player,false);h.succeed();}
    @GameTest public void toolAndGameModeChecksRejectInvalidBoardingAndAcceptOffhandTag(GameTestHelper h){var conveyor=place(h,P);var player=player(h);var packet=request(player,conveyor);player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);h.assertFalse(ChainConveyorInteraction.apply(player,packet),"Empty hands cannot ride");player.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(AllItems.WRENCH));h.assertTrue(ChainConveyorInteraction.apply(player,packet),"Source rideable tag supports offhand tool");ServerChainConveyorHandler.stop(player,false);var adventure=h.makeMockServerPlayer(GameType.ADVENTURE);adventure.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));h.assertFalse(ChainConveyorRidingState.eligible(adventure),"Matches source configuration-packet adventure restriction");h.succeed();}
    @GameTest public void forgedKeepaliveNeverResetsFallDistanceOrCreatesSession(GameTestHelper h){var player=player(h);player.fallDistance=42;h.assertFalse(ServerChainConveyorHandler.heartbeat(player,new ServerChainConveyorHandler.Heartbeat(12345,false)),"No unvalidated keepalive session");h.assertValueEqual(player.fallDistance,42d,"Forged packet does not grant fall protection");h.assertTrue(ServerChainConveyorHandler.get(player)==null,"No implicit boarding");h.succeed();}
    @GameTest public void replayedSessionCannotStopOrExtendAnotherRide(GameTestHelper h){var conveyor=place(h,P);var player=player(h);var packet=request(player,conveyor);ChainConveyorInteraction.apply(player,packet);int old=ServerChainConveyorHandler.get(player).id;ServerChainConveyorHandler.stop(player,false);ChainConveyorInteraction.apply(player,packet);var current=ServerChainConveyorHandler.get(player);current.ttl=3;h.assertFalse(ServerChainConveyorHandler.heartbeat(player,new ServerChainConveyorHandler.Heartbeat(old,true)),"Old stop ignored");h.assertFalse(ServerChainConveyorHandler.heartbeat(player,new ServerChainConveyorHandler.Heartbeat(old,false)),"Old keepalive ignored");h.assertValueEqual(current.ttl,3,"Replayed ID cannot renew new session");ServerChainConveyorHandler.stop(player,false);h.succeed();}
    @GameTest public void keepaliveTimeoutIsTwentyTicksAndValidHeartbeatRenewsIt(GameTestHelper h){var conveyor=place(h,P);var player=player(h);ChainConveyorInteraction.apply(player,request(player,conveyor));var ride=ServerChainConveyorHandler.get(player);for(int i=0;i<10;i++)ServerChainConveyorHandler.tickPlayer(player);h.assertValueEqual(ride.ttl,10,"Ten ticks consumed");h.assertTrue(ServerChainConveyorHandler.heartbeat(player,new ServerChainConveyorHandler.Heartbeat(ride.id,false)),"Live keepalive accepted");for(int i=0;i<19;i++)ServerChainConveyorHandler.tickPlayer(player);h.assertTrue(ServerChainConveyorHandler.get(player)!=null,"Still live before twentieth tick");ServerChainConveyorHandler.tickPlayer(player);h.assertTrue(ServerChainConveyorHandler.get(player)==null,"Expires exactly at source TTL");h.succeed();}
    @GameTest public void shiftAndToolLossEndRideAndDestroyedAnchorCannotKeepItAlive(GameTestHelper h){var conveyor=place(h,P);var player=player(h);var packet=request(player,conveyor);ChainConveyorInteraction.apply(player,packet);player.setShiftKeyDown(true);ServerChainConveyorHandler.tickPlayer(player);h.assertTrue(ServerChainConveyorHandler.get(player)==null,"Shift dismounts");player.setShiftKeyDown(false);ChainConveyorInteraction.apply(player,packet);player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);ServerChainConveyorHandler.tickPlayer(player);h.assertTrue(ServerChainConveyorHandler.get(player)==null,"Tool loss dismounts");player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));ChainConveyorInteraction.apply(player,packet);h.setBlock(P,Blocks.AIR);ServerChainConveyorHandler.tickPlayer(player);h.assertTrue(ServerChainConveyorHandler.get(player)==null,"Missing anchor ends ride");h.succeed();}
    @GameTest(maxTicks=25) public void lookChoosesBranchAndTravelArrivesOnOtherLoop(GameTestHelper h){var a=place(h,P);var b=place(h,Q);a.connectTo(b,null);motor(h,128);h.runAfterDelay(5,()->{var cursor=new ChainConveyorRidingState(a.getBlockPos(),null,54,false);h.assertTrue(cursor.advance(h.getLevel(),new Vec3(1,0,0)),"Loop advanced");h.assertValueEqual(cursor.connection,Q.subtract(P),"Look selected east exit when tangent crossed");h.assertValueEqual(cursor.position,0f,"Travelling starts at zero");for(int i=0;i<30&&cursor.connection!=null;i++)cursor.advance(h.getLevel(),new Vec3(1,0,0));h.assertValueEqual(cursor.anchor,b.getBlockPos(),"Arrived at other loaded conveyor");h.assertTrue(cursor.connection==null,"Returns to looping state");h.assertTrue(Math.abs(cursor.position-305)<.01,"Source arrival tangent angle");h.succeed();});}
    @GameTest(maxTicks=25) public void reversingTravelMirrorsOwnerAndPositionWithoutMovingPhysicalGrip(GameTestHelper h){var a=place(h,P);var b=place(h,Q);a.connectTo(b,null);var motor=motor(h,128);var cursor=new ChainConveyorRidingState(a.getBlockPos(),Q.subtract(P),1.25f,false);var before=new Vec3[1];h.runAfterDelay(5,()->{before[0]=cursor.target(h.getLevel());motor.setGeneratedSpeed(-128);});h.runAfterDelay(9,()->{h.assertTrue(cursor.advance(h.getLevel(),new Vec3(1,0,0)),"Reversal advanced");h.assertValueEqual(cursor.anchor,b.getBlockPos(),"Reversal changes owner");h.assertValueEqual(cursor.connection,P.subtract(Q),"Connection reversed");h.assertTrue(cursor.target(h.getLevel()).distanceToSqr(before[0])<.00001,"Physical hook remains on same strand");h.succeed();});}
    @GameTest(maxTicks=25) public void stoppingNegativeRotationDoesNotFlipRiderToOtherStrand(GameTestHelper h){var a=place(h,P);var b=place(h,Q);a.connectTo(b,null);var motor=motor(h,-64);var cursor=new ChainConveyorRidingState(a.getBlockPos(),Q.subtract(P),1,true);h.runAfterDelay(5,()->motor.setGeneratedSpeed(0));h.runAfterDelay(9,()->{h.assertTrue(cursor.advance(h.getLevel(),new Vec3(1,0,0)),"Stopped chain still holds rider");h.assertValueEqual(cursor.anchor,a.getBlockPos(),"Zero RPM retains last direction");h.assertValueEqual(cursor.position,1f,"Stopped position unchanged");h.succeed();});}
    @GameTest public void reconnectedGenerationCannotCarryStaleRider(GameTestHelper h){var a=place(h,P);var b=place(h,Q);a.connectTo(b,null);var cursor=new ChainConveyorRidingState(a.getBlockPos(),Q.subtract(P),1,false);cursor.edgeId=a.getConnectionId(Q.subtract(P));a.disconnect(Q.subtract(P),h.makeMockPlayer(GameType.CREATIVE));a.connectTo(b,null);h.assertFalse(cursor.advance(h.getLevel(),new Vec3(1,0,0)),"New edge generation invalidates old grip");h.succeed();}
    @GameTest public void reachGraceEndsAndNormalPlayerCollisionMotionRemainsInEffect(GameTestHelper h){var conveyor=place(h,P);var player=player(h);var cursor=new ChainConveyorRidingState(conveyor.getBlockPos(),null,0,false);var target=cursor.target(h.getLevel());var feet=target.subtract(0,player.getBoundingBox().getYsize()+.5*player.getScale(),0);player.setPos(feet);cursor.catchingUp=0;h.assertTrue(cursor.inReach(player,target),"Normal hanging height");player.setPos(feet.add(4,0,0));h.assertFalse(cursor.inReach(player,target),"Separated more than three blocks dismounts");player.setPos(feet.add(0,1.1,0));h.assertFalse(cursor.inReach(player,target),"Player more than one block above grip dismounts");cursor.catchingUp=20;h.assertTrue(cursor.inReach(player,target),"Source initial catching-up grace");h.succeed();}
}
